edit('plastic-landing.php','این صفحه برای مشتریانی است که عباراتی مانند پلاستیک سادات، پخش پلاستیک، بازرگانی سادات پخش، فروش پلاستیک، فروش عمده یا فروش نایلکس را جست‌وجو می‌کنند.','برای خرید بسته‌ای، وزن خالص یا تعداد داخل بسته را کنار قیمت ببینید. برای مصرف فروشگاهی، ابعاد کالا، نوع دسته و مقدار مصرف را مشخص کنید؛ فهرست زیر فقط دسته‌های دارای محصول را نشان می‌دهد.')
edit('wholesale.php','حداقل خرید عمده برای هر محصول جداگانه تعیین می‌شود. برای محصول کیلویی می‌توان این آستانه را مثلاً ۱۰۰ کیلوگرم قرار داد؛ برای کالای بسته‌ای یا عددی، مقدار درج‌شده در واحد همان محصول ملاک است. با رسیدن تعداد همان کالا به آستانه، قیمت عمده خودکار اعمال می‌شود.','حداقل خرید عمده کنار قیمت هر محصول نوشته شده است. مقدار سفارش همان کالا را به حد نصاب برسانید تا قیمت عمده برای تمام واحدهای آن در سبد اعمال شود. تعداد کالاهای متفاوت با هم جمع نمی‌شود.')
edit('wholesale.php','نیازی به درخواست یا تأیید حساب همکاری نیست. هر مشتری پس از ثبت‌نام و ورود می‌تواند وارد پنل فروش عمده شود، قیمت‌ها را مقایسه کند و سفارش خرده یا عمده ثبت کند.','مشاهده قیمت‌ها و افزودن کالا به سبد نیاز به حساب همکاری ندارد. همه مشتریان می‌توانند قیمت خرده و عمده و مبلغ نهایی سبد را مقایسه کنند.')
edit('wholesale.php','مقدار هر کالا در صفحه محصول مشخص است. پیش‌فرض محصولات جدید ۵۰ کیلوگرم است؛ برای محصولات بسته‌ای، تعداد بسته درج‌شده ملاک است. مدیر می‌تواند حداقل هر کالا را جداگانه تعیین کند.','حداقل هر کالا کنار قیمت آن درج شده است و بر اساس واحد فروش همان کالا محاسبه می‌شود. برای مثال، اگر واحد فروش «بسته» باشد، تعداد بسته ملاک است؛ تعداد محصولات متفاوت با هم جمع نمی‌شود.')
